<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

use Civi\Lughauth\Features\OAuth\Profile\Domain\MfaSetup;

/**
 * HTML rendering component for the multi-factor authentication (MFA) configuration panel.
 *
 * This class produces the HTML fragment embedded by ProfileHtml when the user accesses
 * the MFA section of their profile.  It handles two distinct states: an "enabled" state
 * that shows a disable button, and a "disabled" state that presents the TOTP enrolment
 * form together with the provisioning QR code image (when available) and the raw secret.
 *
 * The panel is a pure view component — it carries no application or domain logic and
 * only produces markup from the data it receives, making it straightforward to test
 * in isolation or replace with a template-engine implementation.  All dynamic values
 * are HTML-escaped to prevent XSS vulnerabilities.
 */
class MfaPanel
{
    /**
     * Renders the MFA panel as an HTML string for either the enable or disable workflow.
     *
     * When $enabled is true the panel shows the current status and a disable form.
     * When false it shows the enrolment form with the TOTP seed and optional QR image.
     * Optional $error and $success flags control the display of feedback messages.
     */
    public function render(
        bool $enabled,
        string $saveUrl,
        string $cancelUrl,
        ?MfaSetup $setup = null,
        ?string $error = null,
        bool $success = false,
        array $t = [],
    ): string {
        $saveUrl = htmlspecialchars($saveUrl);
        $cancelUrl = htmlspecialchars($cancelUrl);

        $errorHtml = $error !== null && $error !== ''
            ? '<p class="error">' . htmlspecialchars($error) . '</p>'
            : '';
        $successHtml = $success
            ? '<p class="change-password-success">' . htmlspecialchars($t['success']) . '</p>'
            : '';

        if ($enabled) {
            return <<<HTML
                <h1>{$t['title']}</h1>
                {$successHtml}
                {$errorHtml}
                <p>{$t['enabledHelp']}</p>
                <form method="POST" action="{$saveUrl}" class="change-password-form">
                    <input type="hidden" name="action" value="disable" />
                    <div class="profile-actions">
                        <input class="primary-button" type="submit" value="{$t['disable']}" />
                        <a class="secondary-button" href="{$cancelUrl}">{$t['backToProfile']}</a>
                    </div>
                </form>
                HTML;
        }

        $seed = htmlspecialchars($setup?->seed ?? '');
        $qrImage = $setup?->qrImage ?? null;
        $qrBlock = '';
        if ($qrImage !== null && $qrImage !== '') {
            $qrEscaped = htmlspecialchars($qrImage);
            $qrBlock = '<p><img src="' . $qrEscaped . '" alt="MFA QR" style="max-width:220px;height:auto;" /></p>';
        }

        return <<<HTML
            <h1>{$t['title']}</h1>
            {$successHtml}
            {$errorHtml}
            <p>{$t['help']}</p>
            {$qrBlock}
            <form method="POST" action="{$saveUrl}" class="change-password-form">
                <input type="hidden" name="action" value="enable" />
                <input type="hidden" name="seed" value="{$seed}" />
                <label>{$t['secret']}
                    <input type="text" value="{$seed}" readonly />
                </label>
                <label>{$t['otp']}
                    <input type="text" name="otp" required />
                </label>
                <div class="profile-actions">
                    <input class="primary-button" type="submit" value="{$t['enable']}" />
                    <a class="secondary-button" href="{$cancelUrl}">{$t['cancel']}</a>
                </div>
            </form>
            HTML;
    }
}
